import React from 'react';
import QueryPanel from '../components/QueryPanel/QueryPanel';
import IncidentTable from '../components/IncidentTable/IncidentTable';
import RecommendationCard from '../components/RecommendationCard/RecommendationCard';
import AgentTrace from '../components/AgentTrace/AgentTrace';
import { useQuery } from '../hooks/useSupplyChain';
import './Home.css';

export default function Home() {
  const { loading, error, result, runQuery } = useQuery();

  return (
    <div className="home-page">
      <QueryPanel onSubmit={runQuery} loading={loading} />

      {error && (
        <div className="error-banner">
          <strong>Error:</strong> {error}
        </div>
      )}

      {result && (
        <div className="results-layout">
          <div className="results-main">
            <div className="answer-card">
              <div className="answer-card__label">Risk Assessment</div>
              <p className="answer-card__text">{result.answer}</p>
              <div className="answer-card__meta">
                <span>Confidence: <strong>{(result.confidence_score * 100).toFixed(0)}%</strong></span>
                <span>{result.retrieved_incidents?.length ?? 0} incidents retrieved</span>
              </div>
            </div>

            {result.recommendations?.length > 0 && (
              <section className="results-section">
                <h3 className="section-title">Mitigation Recommendations</h3>
                <div className="rec-list">
                  {result.recommendations.map((rec, i) => (
                    <RecommendationCard key={i} recommendation={rec} index={i} />
                  ))}
                </div>
              </section>
            )}

            {result.retrieved_incidents?.length > 0 && (
              <section className="results-section">
                <IncidentTable incidents={result.retrieved_incidents} title="Retrieved Historical Incidents" />
              </section>
            )}
          </div>

          <div className="results-sidebar">
            <AgentTrace
              agentFindings={result.agent_findings || {}}
              anomalyCorrelations={result.anomaly_correlations || []}
              confidence={result.confidence_score}
            />
          </div>
        </div>
      )}

      {!result && !loading && (
        <div className="home-empty">
          <div className="home-empty__icon">🔍</div>
          <h3>Enter a supply chain query to begin</h3>
          <p>The system will retrieve historical incidents, run multi-agent analysis, and generate actionable mitigation recommendations.</p>
        </div>
      )}
    </div>
  );
}
